    SEQ_NO = #{row.seqNo,jdbcType=VARCHAR},            INTERNAL_KEY = #{row.internalKey,jdbcType=INTEGER},            CLIENT_NO = #{row.clientNo,jdbcType=VARCHAR},            BASE_ACCT_NO = #{row.baseAcctNo,jdbcType=VARCHAR},            PROD_TYPE = #{row.prodType,jdbcType=VARCHAR},            CCY = #{row.ccy,jdbcType=VARCHAR},            ACCT_SEQ_NO = #{row.acctSeqNo,jdbcType=VARCHAR},            PRINCIPAL_AMT = #{row.principalAmt,jdbcType=DECIMAL},            REGISTER_DATE = #{row.registerDate,jdbcType=TIMESTAMP},            MATURITY_DATE = #{row.maturityDate,jdbcType=TIMESTAMP},            FUND_FROM_ACCT_NO = #{row.fundFromAcctNo,jdbcType=VARCHAR},            FUND_FROM_NAME = #{row.fundFromName,jdbcType=VARCHAR},            FUND_FROM_BANK_NO = #{row.fundFromBankNo,jdbcType=VARCHAR},            TRAN_TIMESTAMP = #{row.tranTimestamp,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{row.createTimestamp,jdbcType=VARCHAR},            LAST_CHANGE_DATE = #{row.lastChangeDate,jdbcType=TIMESTAMP},            COMPANY = #{row.company,jdbcType=VARCHAR}

update RB_AUTO_TRAN_INFO
set
    INTERNAL_KEY = #{internalKey,jdbcType=INTEGER},            BASE_ACCT_NO = #{baseAcctNo,jdbcType=VARCHAR},            PROD_TYPE = #{prodType,jdbcType=VARCHAR},            CCY = #{ccy,jdbcType=VARCHAR},            ACCT_SEQ_NO = #{acctSeqNo,jdbcType=VARCHAR},            PRINCIPAL_AMT = #{principalAmt,jdbcType=DECIMAL},            REGISTER_DATE = #{registerDate,jdbcType=TIMESTAMP},            MATURITY_DATE = #{maturityDate,jdbcType=TIMESTAMP},            FUND_FROM_ACCT_NO = #{fundFromAcctNo,jdbcType=VARCHAR},            FUND_FROM_NAME = #{fundFromName,jdbcType=VARCHAR},            FUND_FROM_BANK_NO = #{fundFromBankNo,jdbcType=VARCHAR},            TRAN_TIMESTAMP = #{tranTimestamp,jdbcType=VARCHAR},            CREATE_TIMESTAMP = #{createTimestamp,jdbcType=VARCHAR},            LAST_CHANGE_DATE = #{lastChangeDate,jdbcType=TIMESTAMP},            COMPANY = #{company,jdbcType=VARCHAR}        where SEQ_NO = #{seqNo,jdbcType=VARCHAR}
  and CLIENT_NO = #{clientNo,jdbcType=VARCHAR}
